samples.guides/install-target:
// 1. Which companies / syndicates may this user install on? (Only those — an investor's
//    empty list is not a failure.)
const targets = await wf.installations.eligibleTargets({
  target_type: "syndicate",
});
for (const t of targets)
  console.log(t.id, t.name, t.installed ? "(already installed)" : "");

// 2. Install. The response carries the install (`data`) AND its token. If the app is
//    already installed here the API answers 409 `already_installed`; installOrMintToken
//    mints a fresh token for that existing install instead, re-requesting the same scopes.
//    Any other error (revoked install, missing scope) still throws.
const installed = await wf.installations.installOrMintToken({
  target_type: "syndicate",
  target_id: syndicateId,
  scopes: ["read:syndicates"],
});
const installationToken = installed.token?.access_token; // shown once — store it
if (!installationToken) throw new Error("no installation token returned");

// 3. First request AS the installation.
const asSyndicate = new Wefunder({ accessToken: installationToken });
const deals = await asSyndicate.unwrap(
  asSyndicate.raw.listSyndicateDeals({ path: { syndicate_id: syndicateId } }),
);
console.log(deals.data?.length, "deals");

samples.guides/investment-changed-notifier:
const { visible, first, fields } = data;
if (first === true && visible) return "new investment";
if (!visible) return "canceled or hidden";
// Older events carry `fields` as null or omit it: no hint, no post.
const changed = fields ?? [];
if (changed.includes("status")) return "status changed";
if (changed.includes("amounts")) return "amount changed";
if (changed.includes("group")) return "group changed";
return null; // `reason: "recomputed"` and every other combination

samples.guides/user-token:
// 1. Send the investor to consent. Keep state + the PKCE verifier in their session.
const pkce = generatePkce();
const state = crypto.randomUUID();
await saveAttempt(state, pkce.codeVerifier);
const authorizationUrl = createAuthorizationUrl({
  clientId: process.env.WEFUNDER_CLIENT_ID!,
  redirectUri: process.env.WEFUNDER_REDIRECT_URI!,
  scopes: ["read:investments"],
  state,
  pkce,
});
// redirect(authorizationUrl)

// 2. On the callback, exchange the code (after checking `state` matches the session).
const tokens = await exchangeCode({
  clientId: process.env.WEFUNDER_CLIENT_ID!,
  clientSecret: process.env.WEFUNDER_CLIENT_SECRET, // omit for public clients
  code: "AUTHORIZATION_CODE",
  redirectUri: process.env.WEFUNDER_REDIRECT_URI!,
  codeVerifier: pkce.codeVerifier,
});

// 3. Read their holdings. The access token lasts two hours; the SDK rotates the refresh
//    token for you and hands every new set to `store.save` — persist the whole thing.
const wf = new Wefunder({
  tokens,
  clientId: process.env.WEFUNDER_CLIENT_ID!,
  clientSecret: process.env.WEFUNDER_CLIENT_SECRET,
  store: { save: (next: TokenSet) => persistTokens(next) },
});
const portfolio = await wf.portfolio.get();
console.log(portfolio.attributes?.total_current_value_cents);

